components.calculateValue:
let totaal = 0;
if (data.pv?.arbeid?.totaalNettomaandelijkseInkomstenVanEenStap) {
  totaal += data.pv.arbeid.totaalNettomaandelijkseInkomstenVanEenStap;
}

if (data.pv?.uitkeringen?.totaalNettomaandelijkseInkomstenVanEenStap) {
  totaal += data.pv.uitkeringen.totaalNettomaandelijkseInkomstenVanEenStap;
}

if (data.pv?.onderneming?.totaalNettomaandelijkseInkomstenVanEenStap) {
  totaal += data.pv.onderneming.totaalNettomaandelijkseInkomstenVanEenStap;
}

if (data.pv?.overigeInkomsten?.totaalNettomaandelijkseInkomstenVanEenStap) {
  totaal += data.pv.overigeInkomsten.totaalNettomaandelijkseInkomstenVanEenStap;
}

value = totaal;

components.customDefaultValue:
const indicatorenAlimentatie = ['indicatieBijdrageExPartnerVoorAndereRekeningen'];
if (row?.primairInkomstencomponentType?.code === '1') {
  value = indicatorenAlimentatie.filter(indicator => row[indicator] === true).map(key => ({ indicator: key, parentData: row }));
} else {
  value = [];
}

components.customConditional:
if (row?.primairInkomstencomponentType?.code === '1') {
  show = (row?.indicatieBijdrageExPartnerVoorAndereRekeningen);
} else if (row?.primairInkomstencomponentType?.code === '7') { 
  show = (row?.indicatieMaaltijdvergoeding || row?.indicatieReiskostenvergoeding || row?.indicatieVergoedingInNatura || row?.indicatieOnkostenvergoeding);
} else {
  show = false
}

components.custom:
if (!data.pv.welkeInkomsten.loondienst) {
  data.pv.arbeid.totaalNettomaandelijkseInkomstenVanEenStap = null;  
  data.pv.arbeid.inkomstenComponenten = [];
}

if (!data.pv.welkeInkomsten.uitkeringenPensioenenEnStudiefinanciering) {
  data.pv.uitkeringen.totaalNettomaandelijkseInkomstenVanEenStap = null;  
  data.pv.uitkeringen.inkomstenComponenten = [];
}

if (!data.pv.welkeInkomsten.onderneming) {
  data.pv.onderneming.totaalNettomaandelijkseInkomstenVanEenStap = null;  
  data.pv.onderneming.inkomstenComponenten = [];
}

if (!data.pv.welkeInkomsten.overigeInkomsten) {
  data.pv.overigeInkomsten.totaalNettomaandelijkseInkomstenVanEenStap = null;  
  data.pv.overigeInkomsten.inkomstenComponenten = [];
}

form.submit(); 
component.disabled = true;
